'use strict';
/**
 * registry-top1.test.js — regression guard over the registry-derived top-1
 * retrieval baseline generated by evals/retrieval/gen-registry-top1.js.
 *
 * The skill package ships as a standalone zip of this directory tree
 * (references/ + scripts/), without the repo-root evals/ directory. In that
 * shipped context there is nothing to test against, so this file SKIPS
 * (rather than fails) when evals/retrieval/registry-top1.json is absent.
 *
 * Cases recorded with passes_today:true must still rank their expected
 * lesson id first — that is the regression this test exists to catch. Cases
 * recorded with passes_today:false are pre-existing, known misses; they are
 * reported (not asserted) so the count is visible without failing CI on a
 * gap that isn't a regression.
 */
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

// scripts/tests -> scripts -> claude-code-internals -> skills -> skill-package -> W
const DATA_PATH = path.join(__dirname, '..', '..', '..', '..', '..', 'evals', 'retrieval', 'registry-top1.json');
const SEARCH_JS = path.join(__dirname, '..', 'search.js');

test('registry-derived top-1 identifier cases (evals/retrieval/registry-top1.json)', (t) => {
  if (!fs.existsSync(DATA_PATH)) {
    t.skip('evals/retrieval/registry-top1.json not present (expected in the shipped skill package zip; run node evals/retrieval/gen-registry-top1.js in the full repo to regenerate)');
    return;
  }

  const data = JSON.parse(fs.readFileSync(DATA_PATH, 'utf8'));
  assert.ok(Array.isArray(data.cases), 'registry-top1.json must have a cases array');

  let knownMisses = 0;
  const regressions = [];

  for (const c of data.cases) {
    let topId = null;
    try {
      const out = execFileSync('node', [SEARCH_JS, c.name, '--json', '--top=1'], { encoding: 'utf8' });
      const results = JSON.parse(out);
      topId = results[0] ? results[0].id : null;
    } catch (err) {
      topId = null; // treated as a miss below (stop-words-only or a hard failure)
    }

    if (c.passes_today) {
      if (topId !== c.expected_id) {
        regressions.push(`"${c.name}": expected L${c.expected_id} at rank 1, got ${topId === null ? 'no result' : 'L' + topId}`);
      }
    } else {
      knownMisses++;
    }
  }

  console.log(`registry-top1: ${data.cases.length} cases, ${knownMisses} known misses (not enforced), generated from commit ${data.generated_from_commit || 'unknown'}`);

  assert.deepStrictEqual(regressions, [], `${regressions.length} regression(s):\n  ${regressions.join('\n  ')}`);
});
